const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const btn=(label,action,style='',ic='')=>`<button type="button" class="btn ${style}" data-action="${esc(action)}">${ic?icon(ic):''}${label}</button>`;
const ibtn=(name,action,label=name)=>`<button type="button" class="icon-btn" data-action="${esc(action)}" title="${esc(label)}" aria-label="${esc(label)}">${icon(name)}</button>`;
const initials=n=>(n||'?').split(/[\s@.]+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=(n,i=0)=>`<span class="avatar ${['','blue','gold','green'][i%4]}" title="${esc(n)}">${esc(initials(n))}</span>`;
const date=v=>new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const relative=v=>{const m=Math.floor((Date.now()-new Date(v))/60000);return m<1?'Just now':m<60?`${m} min ago`:m<1440?`${Math.floor(m/60)}h ago`:date(v);};
const colors=[['#9470d3','#efe6fccf','#684a9e'],['#5591d1','#e1effbd4','#376a9f'],['#c79b44','#fff0cbd4','#96711d'],['#4c9a84','#dbf2e9d4','#2e7964']];
const state={user:null,profile:{},envelopes:[],route:'home',filter:'all',search:'',sort:'updated',selected:new Set(),env:null,dirty:false,conflict:false,editorTab:'fields',field:null,recipient:null,tool:null,zoom:1,history:[],future:[],signing:false,signValues:{},consent:false,saving:false,savePromise:null,comments:[],poll:null};
const renderer=new DocumentRenderer();if(localStore)renderer.documentURLResolver=(doc,envelope)=>localStore.documentURL(doc,envelope);let saveTimer,searchTimer;state.changeId=0;
if(localStorage.getItem('velsign-theme')==='dark')document.body.classList.add('dark');
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),error?7500:4200);}
async function api(path,{method='GET',body,raw,headers={}}={}){if(localStore)return localStore.request(path,{method,body,raw,headers});const response=await fetch(assetURL('api/'+path),{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...headers},body:raw??(body?JSON.stringify(body):undefined)});let data;try{data=await response.json();}catch{throw new Error('The server returned an unreadable response.');}if(!response.ok){const e=new Error(data.error||'The request could not be completed.');e.status=response.status;throw e;}return data;}
async function task(fn){try{return await fn();}catch(e){toast(e.message,true);}}
function modal(title,body,footer=''){const d=$('#dialog');d.innerHTML=`<div class="modal-header"><h2>${title}</h2>${ibtn('close','close','Close dialog')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();setTimeout(()=>d.querySelector('input:not([type=file]),textarea,button')?.focus(),0);}
const close=()=>{$('#dialog').close();newKind='agreement';};
function download(bytes,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function hasAction(d){return d.status==='sent'&&(!d.expires||Date.parse(d.expires)>Date.now())&&nextRecipients(d).some(r=>r.email.toLowerCase()===state.user.email);}
function statusName(d){if(d.expires&&Date.parse(d.expires)<Date.now()&&d.status==='sent')return'expired';if(hasAction(d))return'needs';return d.status;}
function badge(d){const s=statusName(d);return `<span class="status ${s}">${icon(({needs:'pen',sent:'clock',completed:'circlecheck',draft:'file',voided:'close',declined:'close',expired:'clock'})[s])}${({needs:'Needs your signature',sent:'Waiting for others',completed:'Completed',draft:'Draft',voided:'Voided',declined:'Declined',expired:'Expired'})[s]}</span>`;}
function updateList(d){const i=state.envelopes.findIndex(x=>x.id===d.id);if(i<0)state.envelopes.unshift(d);else state.envelopes[i]=d;}
async function bootstrap(){const data=await api('bootstrap');Object.assign(state,{user:data.user,profile:data.profile,envelopes:data.envelopes});}
function filtered(){let arr=state.envelopes.filter(d=>d.kind==='agreement');if(state.filter==='waiting')arr=arr.filter(d=>statusName(d)==='sent');else if(state.filter==='needs')arr=arr.filter(hasAction);else if(state.filter!=='all')arr=arr.filter(d=>statusName(d)===state.filter||(state.filter==='sent'&&d.status==='sent'));if(state.search){const q=state.search.toLowerCase();arr=arr.filter(d=>`${d.title} ${d.recipients.map(r=>r.name+' '+r.email).join(' ')}`.toLowerCase().includes(q));}return arr.sort((a,b)=>state.sort==='title'?a.title.localeCompare(b.title):b.updated.localeCompare(a.updated));}
function navItems(){return [['home','home','Overview'],['agreements','files','Agreements'],['templates','template','Templates'],['reports','chart','Reports'],['contacts','users','Contacts']];}
function shell(content){const display=state.profile.name||state.user.name;const nav=navItems();return `<div class="shell"><aside class="sidebar"><a href="#home" class="brand">velsign<em>✳</em></a><div class="workspace-switch"><span class="avatar">${esc(initials(state.profile.company||'My workspace'))}</span><div class="grow"><b>${esc(state.profile.company||'My workspace')}</b><small>Agreement workspace</small></div>${icon('down')}</div><nav aria-label="Main navigation">${nav.map(([route,i,label])=>`<a href="#${route}" title="${label}" class="nav-item ${state.route===route?'active':''}">${icon(i)}<span>${label}</span>${route==='agreements'?`<span class="nav-count">${state.envelopes.filter(d=>d.kind==='agreement').length}</span>`:''}</a>`).join('')}</nav><div class="nav-label">Workspace</div><a class="nav-item ${state.route==='settings'?'active':''}" href="#settings" title="Settings">${icon('settings')}<span>Settings</span></a><div class="sidebar-bottom"><div class="sidebar-note">${icon('shield')}<b class="mt">Your work, all together.</b><p>Prepare agreements, keep track of signatures, and move work forward.</p><button class="text-link" data-action="help">Explore Velsign ${icon('arrow')}</button></div><button class="nav-item" data-action="help" style="border:0;background:transparent" title="Help & resources">${icon('help')}<span>Help & resources</span></button><div class="user-block">${avatar(display)}<div class="grow"><b>${esc(display.split('@')[0])}</b><small>Personal workspace</small></div><a href="#settings" class="icon-btn" aria-label="Profile settings">${icon('down')}</a></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${icon(nav.find(x=>x[0]===state.route)?.[1]||'settings')}<span>${nav.find(x=>x[0]===state.route)?.[2]||'Settings'}</span></div><select class="mobile-nav" aria-label="Navigate workspace" id="mobile-nav">${[...nav,['settings','settings','Settings']].map(([r,i,l])=>`<option value="${r}" ${state.route===r?'selected':''}>${l}</option>`).join('')}</select><div class="top-actions"><div class="search">${icon('search')}<input id="global-search" placeholder="Search your agreements" aria-label="Search your agreements"><span class="key">⌘ K</span></div>${isLocalDemo?'<button class="pill" data-action="local-info">Browser-local demo</button>':''}<span class="top-divider"></span>${ibtn('help','help','Help')}${ibtn('bell','notifications','Activity notifications')}${avatar(display)}</div></header><div class="content">${content}</div></main></div>`;}
function stats(){const agreements=state.envelopes.filter(x=>x.kind==='agreement');const stats=[['needs','pen','Needs your signature',agreements.filter(hasAction).length],['waiting','clock','Waiting for others',agreements.filter(d=>d.status==='sent'&&!hasAction(d)).length],['completed','circlecheck','Completed',agreements.filter(d=>d.status==='completed').length],['draft','file','Drafts',agreements.filter(d=>d.status==='draft').length]];return `<div class="stats">${stats.map(([filter,i,label,value])=>`<button class="stat" data-action="filter:${filter}"><div class="stat-top"><span class="stat-icon">${icon(i)}</span><span class="stat-arrow">↗</span></div><div class="stat-value">${value}</div><div class="stat-bottom"><span class="stat-label">${label}</span></div></button>`).join('')}</div>`;}
function templateCards(){return `<div class="template-grid">${[['nda','shield','Non-disclosure agreement','Business · 1 document'],['consulting','title','Consulting agreement','Services · 1 document'],['offer','users','Employment offer','People · 1 document']].map(([id,i,title,meta])=>`<button class="template-card" data-action="sample:${id}"><span class="template-icon">${icon(i)}</span><div><b>${title}</b><small>${meta}</small></div>${icon('arrow')}</button>`).join('')}</div>`;}
function table(limit=50){const docs=filtered().slice(0,limit);const tabs=[['all','All agreements'],['sent','In progress'],['completed','Completed'],['draft','Drafts']];return `<div class="panel"><div class="table-toolbar"><div class="tabs">${tabs.map(([f,l])=>`<button class="tab ${state.filter===f?'active':''}" data-action="table-filter:${f}">${l}${f==='all'?`<span class="count">${state.envelopes.filter(x=>x.kind==='agreement').length}</span>`:''}</button>`).join('')}</div><div class="row">${state.route==='agreements'?`<div class="search">${icon('search')}<input id="table-search" value="${esc(state.search)}" placeholder="Search agreements" aria-label="Filter agreements"></div>`:''}<select id="sort" class="compact" aria-label="Sort agreements"><option value="updated" ${state.sort==='updated'?'selected':''}>Last updated</option><option value="title" ${state.sort==='title'?'selected':''}>Name A–Z</option></select></div></div>${state.selected.size?`<div class="bulk-bar"><b>${state.selected.size} selected</b>${btn('Export CSV','export-csv','small','download')}${btn('Clear','clear-selection','small quiet')}</div>`:''}<div class="table-wrap"><table><thead><tr><th style="width:35px;padding-right:0"><input type="checkbox" id="select-all" aria-label="Select all visible agreements" ${docs.length&&docs.every(d=>state.selected.has(d.id))?'checked':''}></th><th>Agreement</th><th>Status</th><th>Recipients</th><th>Last updated</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td style="padding-right:0"><input type="checkbox" data-select="${d.id}" aria-label="Select ${esc(d.title)}" ${state.selected.has(d.id)?'checked':''}></td><td><div class="row"><span class="doc-symbol">${icon('file')}</span><div><button class="doc-title" data-action="open:${d.id}">${esc(d.title)}</button><span class="doc-meta">${d.documents.length} document${d.documents.length!==1?'s':''}${d.demo?' · Sample agreement':''}</span></div></div></td><td>${badge(d)}</td><td><div class="recipient-cell">${avatar(d.recipients[0]?.name||'?',state.envelopes.indexOf(d))}<span>${esc(d.recipients[0]?.name?.split('@')[0]||'Add recipients')}${d.recipients.length>1?` <span class="muted">+${d.recipients.length-1}</span>`:''}</span></div></td><td><span>${date(d.updated)}</span><span class="doc-meta">${relative(d.updated)}</span></td><td>${ibtn('more','menu:'+d.id,'Agreement actions')}</td></tr>`).join('')}</tbody></table>${docs.length?'':`<div class="empty">${icon('files')}<h3>No agreements here yet</h3><p>${state.search?'Try another search or filter.':'Upload a document to prepare your first agreement.'}</p>${btn('New agreement','new','primary','plus')}</div>`}</div><div class="table-footer"><span>${docs.length?`Showing ${docs.length} of ${filtered().length} agreements`:'0 agreements'}</span>${state.route==='home'?'<a class="text-link" href="#agreements">View all agreements '+icon('arrow')+'</a>':'<span>Sorted by '+(state.sort==='title'?'name':'latest activity')+'</span>'}</div></div>`;}
function home(){const name=(state.profile.name||state.user.name).split(/[ @]/)[0];return `<div class="page-heading"><div><h1>Welcome back, ${esc(name)} <span style="font-size:23px;font-weight:400">✧</span></h1><p>Here’s what’s happening with your agreements.</p></div><div class="date-range">${icon('calendar')}${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'long',year:'numeric'})}</div></div>${stats()}<section class="action-banner"><div><h2>Ready for your next agreement?</h2><p>Add your document. Choose your recipients. Get it signed.</p><div class="row">${btn('New agreement','new','primary','plus')}${btn('Use a template','go:templates','','template')}</div></div><div class="banner-mark" aria-hidden="true">${icon('signature')}</div></section><section><div class="section-head"><h2 class="section-title">Recent agreements</h2>${btn('Refresh','refresh','small quiet','redo')}</div>${table(6)}</section><section class="templates-strip"><div class="section-head"><h2 class="section-title">Start with a template</h2><a class="text-link" href="#templates">View templates ${icon('arrow')}</a></div>${templateCards()}<p class="sample-caption">Sample documents to help you get started. Review and adapt before use.</p></section>`;}
function agreements(){return `<div class="page-heading"><div><h1>Agreements</h1><p>Every document, from first draft to final signature.</p></div>${btn('New agreement','new','primary','plus')}</div>${stats()}${table(200)}`;}
function templates(){const saved=state.envelopes.filter(d=>d.kind==='template');return `<div class="page-heading"><div><h1>Templates</h1><p>A head start for the agreements you use most.</p></div>${btn('Create template','new-template','primary','plus')}</div><div class="section-head"><h2 class="section-title">Starter templates</h2><span class="pill">Sample documents</span></div>${templateCards()}<div class="section-head" style="margin-top:35px"><h2 class="section-title">Your templates</h2><span class="muted small-text">${saved.length} templates</span></div>${saved.length?`<div class="template-grid">${saved.map(d=>`<div class="panel report-card"><span class="template-icon">${icon('template')}</span><h3 style="font-size:16px">${esc(d.title)}</h3><p class="small-text muted">${d.documents.length} documents · ${d.fields.length} fields</p><div class="row">${btn('Use template','use:'+d.id,'small primary')}${btn('Edit','open:'+d.id,'small')}</div></div>`).join('')}</div>`:`<div class="panel empty">${icon('template')}<h3>Your repeatable workflows start here</h3><p>Save a document, recipient roles, and fields as a reusable template.</p>${btn('Create template','new-template','','plus')}</div>`}`;}
function reports(){const arr=state.envelopes.filter(x=>x.kind==='agreement');const counts=['draft','sent','completed','declined','voided'].map(s=>[s,arr.filter(x=>x.status===s).length]);const max=Math.max(1,...counts.map(x=>x[1]));const completed=arr.filter(x=>x.completed);const hours=completed.map(x=>(Date.parse(x.completed)-Date.parse(x.activated||x.created))/36e5);return `<div class="page-heading"><div><h1>Agreement insights</h1><p>A live view of the agreements in your workspace.</p></div>${btn('Export report','export-csv','','download')}</div>${stats()}<div class="report-grid"><div class="panel report-card"><h2 class="section-title">Agreement status</h2><p class="muted small-text">All time · ${arr.length} agreements</p><div class="bars">${counts.map(([s,n])=>`<div class="bar-group"><div class="bar" style="height:${n/max*90}%;${s==='completed'?'background:#7ac5a6':''}"><span>${n}</span></div><span class="bar-label">${s[0].toUpperCase()+s.slice(1)}</span></div>`).join('')}</div></div><div class="panel report-card"><h2 class="section-title">Signing performance</h2><div style="font-size:44px;margin:30px 0 8px;letter-spacing:-1px">${arr.length?Math.round(completed.length/arr.length*100):0}<span style="font-size:24px">%</span></div><p class="muted small-text">Completion rate across all agreements</p><div class="divider"></div><div class="between"><span class="small-text">Average completion time</span><b>${hours.length?(hours.reduce((a,b)=>a+b)/hours.length).toFixed(1)+' h':'—'}</b></div><div class="between mt"><span class="small-text">Awaiting signature</span><b>${arr.filter(d=>d.status==='sent').length}</b></div></div></div>`;}
async function contactsView(){const contacts=await api('contacts');$('#app').innerHTML=shell(`<div class="page-heading"><div><h1>Contacts</h1><p>The people you work with, ready for your next agreement.</p></div>${btn('Add contact','contact-new','primary','plus')}</div>${contacts.length?`<div class="contact-grid">${contacts.map((c,i)=>`<div class="panel contact-card"><div class="between">${avatar(c.name,i)}${ibtn('trash','contact-delete:'+c.id,'Remove contact')}</div><h3>${esc(c.name)}</h3><p>${esc(c.email)}</p><p>${esc(c.company||'No company added')}</p></div>`).join('')}</div>`:`<div class="panel empty">${icon('users')}<h3>Keep your contacts close</h3><p>Add the people you regularly send agreements to.</p>${btn('Add your first contact','contact-new','','plus')}</div>`}`);}
function settings(){return `<div class="page-heading"><div><h1>Workspace settings</h1><p>Make Velsign work the way you do.</p></div></div><div class="settings-grid"><div class="settings-nav"><button class="active" data-action="settings-tab:profile">My profile</button><button data-action="settings-tab:appearance">Appearance</button><button data-action="settings-tab:workspace">Workspace & access</button></div><div id="settings-content">${profileSettings()}</div></div>`;}
function profileSettings(){return `<div class="panel settings-card"><h2>My profile</h2><p>Your name appears in comments and agreement activity.</p><form id="profile-form"><div class="divider"></div><div class="form-field"><label for="profile-name">Display name</label><input id="profile-name" name="name" value="${esc(state.profile.name||state.user.name)}" required maxlength="150"></div><div class="form-field"><label>Account email</label><input value="${esc(state.user.email)}" readonly><div class="form-help">${isLocalDemo?'This is a local demonstration identity, not a verified signing account.':'Your signing identity is verified by your account.'}</div></div><div class="form-field"><label for="company-name">Workspace name</label><input id="company-name" name="company" value="${esc(state.profile.company||'')}" placeholder="My workspace" maxlength="150"></div><div class="form-field"><label for="signature-name">Default typed signature</label><input id="signature-name" name="signature" value="${esc(state.profile.signature||'')}" maxlength="150" placeholder="Your full name"></div><button class="btn primary" type="submit">Save changes</button></form></div>`;}
async function route(){clearInterval(state.poll);clearTimeout(saveTimer);if(state.env){renderer.clearPages();state.env=null;}state.signing=false;state.dirty=false;state.conflict=false;state.selected.clear();const parts=location.hash.slice(1).split('/');const view=parts[0]||'home';if(view==='agreement'||view==='sign'){await openEditor(parts[1],view==='sign'?{recipient:parts[2],token:parts[3]}:null);return;}state.route=['home','agreements','templates','reports','contacts','settings'].includes(view)?view:'home';if(state.route==='contacts'){await contactsView();return;}$('#app').innerHTML=shell(({home,agreements,templates,reports,settings})[state.route]());}
function renderView(){if(state.env)return;$('#app').innerHTML=shell(({home,agreements,templates,reports,settings})[state.route]?.()||home());}
function pendingSignature(){return state.signing&&state.env&&Object.keys(state.signValues).some(k=>state.signValues[k]!==state.env.values[k]);}
function confirmLeaving(to){modal('Leave your signing session?',`<p class="long-text">You have signature fields that have not been submitted. Stay to finish signing, or discard the entered values.</p>`,btn('Stay here','close','primary')+btn('Discard & leave','discard-signing:'+to,'danger'));}
async function navigate(to){if(pendingSignature()){confirmLeaving(to);return;}if(state.dirty){await save();if(state.dirty)return;}history.pushState({},'','#'+to);await route();}
let uploads=[],newKind='agreement';
function newAgreement(kind='agreement'){uploads=[];uploadEpoch++;pendingUploads=0;newKind=kind;modal(kind==='template'?'Create a template':'New agreement',`<div class="form-field"><label for="new-title">${kind==='template'?'Template':'Agreement'} name</label><input id="new-title" placeholder="e.g. Design services agreement" maxlength="200"></div><label class="dropzone" id="dropzone">${icon('upload')}<b>Drop your document here</b><p>PDF, PNG, or JPG · Up to 10 MB per file<br>PDFs up to 100 pages, with unrotated pages</p><input type="file" id="upload-input" multiple accept="application/pdf,image/png,image/jpeg"></label><div id="uploads"></div><div class="divider"></div><div class="between"><span class="small-text muted">Just exploring?</span><button class="text-link" data-action="sample:consulting">Use a sample document ${icon('arrow')}</button></div>`,btn('Cancel','close')+btn('Continue','create','primary','arrow'));const zone=$('#dropzone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover');};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');task(()=>uploadFiles(e.dataTransfer.files));};}
let uploadEpoch=0,pendingUploads=0;
async function uploadFiles(files){const epoch=uploadEpoch;pendingUploads++;try{for(let file of files){if(file.size>10*1024*1024){toast('Each document must be under 10 MB.',true);continue;}if(['image/png','image/jpeg'].includes(file.type))file=await imageToPDF(file);const item=document.createElement('div');item.className='upload-item';item.textContent='Uploading '+file.name+'…';$('#uploads')?.append(item);try{const doc=await api('files',{method:'POST',raw:await file.arrayBuffer(),headers:{'Content-Type':'application/pdf','X-Filename':encodeURIComponent(file.name)}});if(epoch!==uploadEpoch)continue;uploads.push(doc);item.innerHTML=icon('circlecheck')+`<div class="grow"><b>${esc(doc.name)}</b><div class="small-text muted">${doc.pages.length} pages · ${(doc.size/1024).toFixed(0)} KB</div></div>`;if(!$('#new-title')?.value&&$('#new-title'))$('#new-title').value=doc.name.replace(/\.pdf$/i,'');}catch(e){item.textContent=e.message;item.style.color='#b43d53';}}}finally{if(epoch===uploadEpoch)pendingUploads--;} }
async function createAgreement(){if(pendingUploads)throw new Error('Wait until all documents finish uploading.');const title=$('#new-title')?.value.trim();if(!title)throw new Error('Give your agreement a name.');if(!uploads.length)throw new Error('Upload a document to continue.');const d=await api('envelopes',{method:'POST',body:{title,kind:newKind,documents:uploads}});updateList(d);close();await navigate('agreement/'+d.id);await recipientsDialog();}
async function sampleAgreement(key){const names={nda:'Mutual non-disclosure agreement',consulting:'Consulting services agreement',offer:'Employment offer letter'};if(!names[key])return;const d=await api('envelopes',{method:'POST',body:{title:names[key],kind:newKind,documents:[{builtin:key,name:names[key]+'.pdf'}]}});updateList(d);close();await navigate('agreement/'+d.id);await recipientsDialog();}
async function envelopeMenu(id){const d=await api('envelopes/'+id);modal(esc(d.title),`<div class="stack">${badge(d)}<div class="review-grid"><div class="review-box"><b>${d.documents.length} documents</b><small>${d.fields.length} assigned fields</small></div><div class="review-box"><b>${d.recipients.length} recipients</b><small>Updated ${date(d.updated)}</small></div></div><div class="stack">${btn(d.status==='draft'?'Continue preparing':'Open agreement','open:'+id,'','file')}${hasAction(d)?btn('Review & sign','sign-own:'+id,'primary','pen'):''}${['owner','editor'].includes(d.permission)?btn('Create a copy','duplicate:'+id,'','copy'):''}${d.permission==='owner'?btn('Save as template','template:'+id,'','template'):''}${btn('Download documents','download:'+id,'','download')}${btn('Signing record','receipt:'+id,'','shield')}${d.permission==='owner'&&['draft','sent'].includes(d.status)?btn('Void agreement','void:'+id,'danger','close'):''}</div></div>`);}
async function recipientsDialog(){await save();const d=state.env;if(!d||d.status!=='draft')return;const contacts=await api('contacts');const rows=d.recipients.length?structuredClone(d.recipients):[{id:uid(),name:state.profile.name||state.user.name,email:state.user.email,role:'signer',order:1}];function paint(){modal('Add recipients',`<p class="muted small-text" style="margin-top:0">Choose who needs to sign, approve, or receive a copy.</p><label class="inline" style="margin-bottom:20px"><input type="checkbox" id="sequential" ${d.sequential?'checked':''}> Set a signing order</label><div id="recipients-form">${rows.map((r,i)=>`<div class="recipient-edit" data-recipient-id="${r.id}"><div class="recipient-edit-head">${avatar(r.name||'Recipient',i)}<b class="small-text grow">Recipient ${i+1}</b>${ibtn('trash','remove-recipient:'+r.id,'Remove recipient')}</div><div class="form-grid recipient-grid"><div><label>Name</label><input data-key="name" value="${esc(r.name)}" maxlength="150" placeholder="Full name" list="contact-names"></div><div><label>Email</label><input data-key="email" type="email" value="${esc(r.email)}" placeholder="name@company.com"></div><div><label>Action</label><select data-key="role">${[['signer','Needs to sign'],['approver','Needs to approve'],['cc','Receives a copy']].map(([v,l])=>`<option value="${v}" ${r.role===v?'selected':''}>${l}</option>`).join('')}</select></div><div><label>Signing order</label><input data-key="order" type="number" min="1" max="25" value="${r.order}"></div></div></div>`).join('')}</div><datalist id="contact-names">${contacts.map(c=>`<option value="${esc(c.name)}">${esc(c.email)}</option>`).join('')}</datalist>${btn('Add recipient','add-recipient','','plus')}<div class="divider"></div><label class="inline"><input type="checkbox" id="only-me"> Only I need to sign</label>`,btn('Cancel','close')+btn('Save recipients','save-recipients','primary','arrow'));$('#dialog').querySelector('[data-action="add-recipient"]').onclick=()=>{collect();rows.push({id:uid(),name:'',email:'',role:'signer',order:rows.length+1});paint();};$$('[data-action^="remove-recipient:"]').forEach(b=>b.onclick=()=>{collect();const rid=b.dataset.action.split(':')[1];rows.splice(rows.findIndex(r=>r.id===rid),1);paint();});$('#only-me').onchange=e=>{if(e.target.checked){rows.splice(0,rows.length,{id:uid(),name:state.profile.name||state.user.name,email:state.user.email,role:'signer',order:1});paint();}};$$('[data-key="name"]').forEach(input=>input.onchange=()=>{const c=contacts.find(x=>x.name===input.value);if(c)$('[data-key="email"]',input.closest('.recipient-edit')).value=c.email;});$('#dialog').querySelector('[data-action="save-recipients"]').onclick=()=>task(async()=>{if(state.env!==d||state.conflict)throw new Error('The agreement changed while this dialog was open. Close it and resolve the newer version first.');collect();const removed=d.fields.filter(f=>!rows.some(r=>r.id===f.recipient&&r.role!=='cc'));if(removed.length)toast(`${removed.length} fields removed with their recipients.`);const fields=d.fields.filter(f=>rows.some(r=>r.id===f.recipient&&r.role!=='cc'));const candidate={...d,recipients:rows,fields};validateDocument(candidate);d.recipients=rows;d.fields=fields;state.recipient=rows.find(x=>x.role!=='cc')?.id;markDirty();await save();if(!state.dirty){close();renderEditor();}});}
function collect(){for(const el of $$('.recipient-edit')){const row=rows.find(r=>r.id===el.dataset.recipientId);for(const input of $$('[data-key]',el))row[input.dataset.key]=input.dataset.key==='order'?Number(input.value):input.value.trim();}d.sequential=$('#sequential').checked;}paint();}
async function openEditor(id,sign=null){clearInterval(state.poll);const d=await api(sign?`sign/${id}/${sign.recipient}${sign.token?'?token='+encodeURIComponent(sign.token):''}`:'envelopes/'+id);state.env=d;state.signing=!!sign;state.signRecipient=sign?.recipient;state.signToken=sign?.token;state.signValues={...d.values};state.consent=false;state.editorTab='fields';state.field=null;state.recipient=d.recipients.find(x=>x.role!=='cc')?.id;state.tool=null;state.history=[];state.future=[];state.dirty=false;state.conflict=false;state.zoom=innerWidth<680?.7:1;renderEditor();state.poll=setInterval(()=>task(pollChanges),5000);await pollChanges();}
function canEdit(){return state.env?.status==='draft'&&['owner','editor'].includes(state.env.permission)&&!state.signing;}
function renderEditor(){const d=state.env;if(!d)return;const edit=canEdit();const required=d.fields.filter(f=>f.recipient===state.signRecipient&&f.required&&visible(f,state.signValues));const done=required.filter(f=>valueValid(f,state.signValues[f.id])).length;$('#app').innerHTML=`<div class="editor"><header class="editor-top">${ibtn('back','leave-editor','Back to agreements')}<a class="brand" href="#home">velsign<em>✳</em></a><div class="editor-title"><b>${esc(d.title)}</b><small id="save-state">${state.signing?'Review and sign':`${d.kind==='template'?'Template':'Agreement'} · ${state.dirty?'Unsaved changes':'All changes saved'}`}${d.demo?' · Sample document':''}</small></div><div class="actions">${!state.signing&&!isLocalDemo?btn('Share','collaborators','optional','users'):''}${isLocalDemo?'<button class="pill optional" data-action="local-info">Local demo</button>':''}${!state.signing?btn('Download','download:'+d.id,'optional','download'):''}${edit?btn('Save','save','','save'):''}${edit&&d.kind==='agreement'?btn('Review & activate','review','primary','arrow'):hasAction(d)&&!state.signing?btn('Review & sign','sign-own:'+d.id,'primary','pen'):state.signing&&d.status==='sent'?btn(d.recipients.find(r=>r.id===state.signRecipient)?.role==='approver'?'Approve':'Finish signing','finish','primary','check'):badge(d)}</div></header>${state.signing?`<div class="signing-banner"><div><strong>${d.status==='completed'?'This agreement is complete':`${done} of ${required.length} required fields complete`}</strong> <span class="optional">· ${esc(d.recipients.find(r=>r.id===state.signRecipient)?.name)}</span></div>${d.status==='sent'?btn('Next required field','next-field','small','arrow'):btn('Download agreement','download:'+d.id,'small','download')}</div>`:''}<div class="editor-bar"><div class="editor-tabs">${ibtn('menu','toggle-tools','Show document tools')}${ibtn('settings','toggle-properties','Show field properties')}${[['fields',edit?'Prepare':'Document'],['recipients','Recipients'],['comments','Comments'],['activity','Activity']].filter(([tab])=>!state.signing||tab==='fields').map(([tab,label])=>`<button class="tab ${state.editorTab===tab?'active':''}" data-action="editor-tab:${tab}">${label}</button>`).join('')}</div><div class="row"><span id="presence" class="presence"></span>${edit?ibtn('undo','undo','Undo (Ctrl+Z)')+ibtn('redo','redo','Redo (Ctrl+Shift+Z)'):''}<select id="zoom" class="compact" aria-label="Document zoom">${[.5,.7,.85,1,1.25,1.5,2].map(z=>`<option value="${z}" ${state.zoom===z?'selected':''}>${z*100}%</option>`).join('')}</select></div></div><div class="editor-layout"><aside class="field-sidebar" id="left-panel">${leftPanel()}</aside><div class="viewport" id="viewport"><div class="page-stack">${d.documents.map(doc=>doc.pages.map((p,i)=>`<article class="paper" data-document="${doc.id}" data-page="${i}" style="width:${p.width*state.zoom}px;height:${p.height*state.zoom}px" aria-label="${esc(doc.name)}, page ${i+1}"><canvas data-document="${doc.id}" data-page="${i}" aria-label="${esc(doc.name)}, page ${i+1}"></canvas><div class="fields-layer"></div><span class="page-label">${esc(doc.name)} · ${i+1} / ${doc.pages.length}</span></article>`).join('')).join('')||`<div class="empty"><h3>Add a document to get started</h3>${btn('Add document','add-document','','upload')}</div>`}</div></div><aside class="detail-sidebar" id="right-panel">${rightPanel()}</aside></div></div>`;renderFields();renderer.observe($('#viewport'),d.documents,d.id,state.zoom);bindPages();if(state.editorTab==='comments')task(loadComments);}
function leftPanel(){const d=state.env;const edit=canEdit();if(state.signing){const r=d.recipients.find(x=>x.id===state.signRecipient);return `<h2 class="sidebar-heading">Your signing session</h2><div class="recipient-card">${avatar(r?.name)}<div><b>${esc(r?.name)}</b><small>${esc(r?.email)}</small></div></div><p class="palette-help">Review all pages, then complete the highlighted fields.</p><div class="notice">${esc(d.message)}</div><div class="divider"></div><label class="inline" style="align-items:flex-start;line-height:1.7;font-size:12px"><input type="checkbox" id="consent" ${state.consent?'checked':''}> I agree to use electronic records and signatures for this agreement.</label><button class="text-link mt" data-action="disclosure">Read the disclosure</button><div class="divider"></div>${btn('Read document text','document-text','small full-width','text')}${d.status==='sent'?btn('Decline to sign','decline','small quiet danger full-width mt'):''}`;}
if(state.editorTab==='recipients')return `<div class="between"><h2 class="sidebar-heading" style="margin:0">Recipients</h2>${edit?ibtn('pen','recipients','Edit recipients'):''}</div>${d.recipients.map((r,i)=>`<div class="recipient-card">${avatar(r.name,i)}<div><b>${d.sequential?r.order+'. ':''}${esc(r.name)}</b><small>${esc(r.email)}</small><small>${({signer:'Needs to sign',approver:'Needs to approve',cc:'Receives a copy'})[r.role]} · ${r.status||'Draft'}</small>${d.status==='sent'&&d.permission==='owner'&&r.role!=='cc'?`<button class="text-link" data-action="link:${r.id}">Get signing link</button>`:''}</div></div>`).join('')||'<p class="palette-help">No recipients added yet.</p>'}${edit?btn('Edit recipients','recipients','full-width mt','users'):''}`;
if(state.editorTab==='activity')return `<h2 class="sidebar-heading">Agreement activity</h2>${activityHTML(d)}${btn('Download record','receipt:'+d.id,'small full-width','download')}`;
if(state.editorTab==='comments')return `<h2 class="sidebar-heading">Team comments</h2><p class="form-help">${isLocalDemo?'Local notes are saved in this browser.':'Comments are visible to workspace collaborators.'}</p><div id="comments-list"></div>${['owner','editor'].includes(d.permission)?`<form id="comment-form" class="mt"><label for="comment-text">Add a comment</label><textarea id="comment-text" maxlength="4000" placeholder="Leave a note for your team…" required></textarea><button class="btn primary small full-width mt" type="submit">Post comment</button></form>`:''}`;
if(!edit)return `<h2 class="sidebar-heading">Agreement details</h2>${badge(d)}<p class="palette-help">${d.documents.length} documents<br>${d.recipients.length} recipients<br>Created ${date(d.created)}</p>${d.expires?`<p class="form-help">Expires ${date(d.expires)}</p>`:''}${hasAction(d)?btn('Review & sign','sign-own:'+d.id,'primary full-width','pen'):''}${d.status==='sent'&&d.permission==='owner'?btn('Signing links','signing-links','full-width mt','send'):''}<div class="divider"></div>${btn('Read document text','document-text','small full-width','text')}${btn('Activity record','receipt:'+d.id,'small full-width mt','shield')}`;
return `<h2 class="sidebar-heading">Assign fields to</h2><select id="field-recipient" aria-label="Field recipient">${d.recipients.filter(r=>r.role!=='cc').map(r=>`<option value="${r.id}" ${state.recipient===r.id?'selected':''}>${esc(r.name)}</option>`).join('')||'<option>Add a recipient first</option>'}</select>${btn('Edit recipients','recipients','quiet small full-width','users')}<div class="divider" style="margin-top:14px"></div><h2 class="sidebar-heading">Standard fields</h2><div class="palette">${FIELD_TYPES.map(type=>`<button type="button" draggable="true" data-tool="${type}" class="${state.tool===type?'active':''}" title="Add ${type} field">${icon(type)}${type[0].toUpperCase()+type.slice(1)}</button>`).join('')}</div><p class="palette-help">Drag a field onto the page, or choose a field and click to place it.</p>${btn('Auto-place signature fields','auto-fields','small full-width','signature')}<div class="divider"></div>${btn('Add document','add-document','small full-width','upload')}`;}
function rightPanel(){const d=state.env;const f=d.fields.find(x=>x.id===state.field);if(f&&canEdit()){const r=d.recipients.find(x=>x.id===f.recipient);return `<div class="between"><h2 class="sidebar-heading" style="margin:0">Field properties</h2>${ibtn('close','deselect','Deselect field')}</div><div class="divider"></div><div class="field-property"><label for="prop-label">Label</label><input id="prop-label" data-prop="label" value="${esc(f.label||f.type)}" maxlength="100"></div><div class="field-property"><label>Assigned recipient</label><select data-prop="recipient">${d.recipients.filter(x=>x.role!=='cc').map(r=>`<option value="${r.id}" ${f.recipient===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="field-property"><label class="inline"><input type="checkbox" data-prop="required" ${f.required?'checked':''}> Required field</label></div>${f.type==='dropdown'?`<div class="field-property"><label>Options, one per line</label><textarea data-prop="options">${esc((f.options||[]).join('\n'))}</textarea></div>`:''}<div class="form-grid"><div class="field-property"><label>Width (%)</label><input type="number" min="2" max="100" data-prop="w" value="${Math.round(f.w*100)}"></div><div class="field-property"><label>Height (%)</label><input type="number" min="2" max="100" data-prop="h" value="${Math.round(f.h*100)}"></div></div><div class="field-property"><label>Show when</label><select data-prop="conditionField"><option value="">Always visible</option>${d.fields.filter(x=>x.id!==f.id&&x.recipient===f.recipient&&!x.condition&&!['signature','initials','date'].includes(x.type)).map(x=>`<option value="${x.id}" ${f.condition?.field===x.id?'selected':''}>${esc(x.label||x.type)}</option>`).join('')}</select></div>${f.condition?`<div class="field-property"><label>Equals value</label><input data-prop="conditionValue" value="${esc(f.condition.equals)}"><div class="form-help">For a checkbox, enter true or false.</div></div>`:''}<div class="divider"></div>${btn('Duplicate field','duplicate-field','small full-width','copy')}${btn('Delete field','delete-field','small full-width danger mt','trash')}<p class="form-help mt">Arrow keys move a selected field.<br>Shift + arrow moves it further.<br>Delete removes it.</p>`;}
return `<h2 class="sidebar-heading">Documents</h2>${d.documents.map(doc=>`<button class="doc-thumb" data-action="scroll-doc:${doc.id}"><span class="doc-symbol">${icon('file')}</span><span><b>${esc(doc.name)}</b><small>${doc.pages.length} pages</small></span></button>`).join('')}<div class="divider"></div><div class="between small-text"><span class="muted">Fields</span><b>${d.fields.length}</b></div><div class="between small-text mt"><span class="muted">Recipients</span><b>${d.recipients.length}</b></div><p class="palette-help">${canEdit()?'Select a field to adjust its label, size, recipient, or visibility.':'The activity record tracks document preparation and signing.'}</p>${state.env.demo?'<span class="pill">Sample document</span>':''}`;}
function activityHTML(d){return `<ol class="timeline">${[...d.audit].reverse().map(e=>`<li><b>${esc(e.type)}</b><small>${esc(e.actor)}<br>${relative(e.at)}</small>${e.detail?`<small>${esc(e.detail.length>110?e.detail.slice(0,110)+'…':e.detail)}</small>`:''}</li>`).join('')}</ol>`;}
function renderFields(){const d=state.env;const edit=canEdit();for(const paper of $$('.paper')){const layer=$('.fields-layer',paper);const fields=d.fields.filter(f=>f.document===paper.dataset.document&&f.page===Number(paper.dataset.page));layer.innerHTML=fields.filter(f=>!state.signing||visible(f,state.signValues)).map(f=>{const val=(state.signing?state.signValues:d.values)[f.id];const has=val!==undefined&&val!==null&&val!==''&&val!==false;const mine=state.signing&&f.recipient===state.signRecipient&&d.status==='sent'&&d.recipients.find(r=>r.id===f.recipient)?.status!=='completed';const doc=d.documents.find(x=>x.id===f.document);const page=doc.pages[f.page];let renderedValue='';if(has&&!(typeof val==='string'&&val.startsWith('data:image/png;base64,'))){const text=val===true?'✓':String(val);const layout=fitText(text,f.w*page.width,f.h*page.height,(t,size)=>{measureContext.font=size+'px Arial';return measureContext.measureText(t).width;});renderedValue=`<span style="font:normal ${layout.size*state.zoom}px/1.2 Arial;white-space:pre-wrap;display:block;width:100%;text-overflow:clip">${layout.lines.map(esc).join('\n')}</span>`;}const [color,bg,ink]=colors[Math.max(0,d.recipients.findIndex(r=>r.id===f.recipient))%4];return `<div role="button" tabindex="0" aria-label="${esc(f.label||f.type)}${f.required?', required':''}" data-field="${f.id}" class="field ${state.field===f.id?'selected':''} ${has?'filled':''} ${mine?'signable':edit?'':'readonly'}" style="left:${f.x*100}%;top:${f.y*100}%;width:${f.w*100}%;height:${f.h*100}%;--field-color:${color};--field-bg:${bg};--field-ink:${ink}">${has?(typeof val==='string'&&val.startsWith('data:image/png;base64,')?`<img src="${esc(val)}" alt="Applied signature">`:renderedValue):`${icon(f.type)}<span>${esc(f.label||f.type[0].toUpperCase()+f.type.slice(1))}</span>${f.required?'<span class="required-star">*</span>':''}`}${state.field===f.id&&edit?['nw','n','ne','e','se','s','sw','w'].map(g=>`<i class="grip ${g}" data-grip="${g}"></i>`).join(''):''}</div>`;}).join('');}}
function bindPages(){$$('[data-tool]').forEach(b=>{b.ondragstart=e=>{e.dataTransfer.setData('text/velsign-field',b.dataset.tool);e.dataTransfer.effectAllowed='copy';};b.onclick=()=>{state.tool=b.dataset.tool;if(!state.recipient){task(recipientsDialog);return;}$$('[data-tool]').forEach(x=>x.classList.toggle('active',x===b));toast(`Click on a page to add ${state.tool}.`);};});for(const paper of $$('.paper')){paper.ondragover=e=>{if(canEdit()){e.preventDefault();e.dataTransfer.dropEffect='copy';}};paper.ondrop=e=>{e.preventDefault();const type=e.dataTransfer.getData('text/velsign-field');if(FIELD_TYPES.includes(type))addField(type,paper,e.clientX,e.clientY);};paper.onpointerdown=e=>{const target=e.target.closest('[data-field]');if(target){if(state.signing){e.preventDefault();task(()=>signField(target.dataset.field));return;}if(!canEdit())return;startDrag(e,target,paper);return;}if(canEdit()&&state.tool)addField(state.tool,paper,e.clientX,e.clientY);else if(canEdit()){state.field=null;renderFields();$('#right-panel').innerHTML=rightPanel();}};}}
function snapshot(){state.history.push(structuredClone(state.env.fields));if(state.history.length>80)state.history.shift();state.future=[];}
function markDirty(){state.changeId++;state.dirty=true;const el=$('#save-state');if(el)el.textContent=state.conflict?'New version available · changes kept here':'Unsaved changes';clearTimeout(saveTimer);if(!state.conflict)saveTimer=setTimeout(()=>task(save),1000);}
async function save(){if(!state.env||!state.dirty||!canEdit()||state.conflict)return;if(state.saving){await state.savePromise;if(state.dirty)return save();return;}const env=state.env;const submittedChange=state.changeId;const submitted={title:env.title,documents:structuredClone(env.documents),recipients:structuredClone(env.recipients),fields:structuredClone(env.fields),sequential:env.sequential,message:env.message,expires:env.expires};state.saving=true;$('#save-state')&&($('#save-state').textContent='Saving…');state.savePromise=(async()=>{try{const d=await api(`envelopes/${env.id}/action`,{method:'POST',body:{revision:env.revision,action:'edit',payload:submitted}});if(state.env!==env)return;const changed=state.changeId!==submittedChange;env.revision=d.revision;env.audit=d.audit;env.updated=d.updated;if(!changed)env.documents=d.documents;updateList({...env});state.dirty=changed;$('#save-state')&&($('#save-state').textContent=changed?'Unsaved changes':'All changes saved');if(changed)saveTimer=setTimeout(()=>task(save),700);}catch(e){if(e.status===409){state.conflict=true;$('#save-state')&&($('#save-state').innerHTML='New changes available · <button class="text-link" data-action="conflict">Resolve</button>');}throw e;}finally{state.saving=false;}})();return state.savePromise;}
function addField(type,paper,clientX,clientY){if(!canEdit())return;if(!state.recipient){task(recipientsDialog);return;}snapshot();const rect=paper.getBoundingClientRect();const w=type==='checkbox'?.035:type==='signature'?.27:.2;const h=type==='signature'?.05:.032;const f={id:uid(),type,label:type[0].toUpperCase()+type.slice(1),document:paper.dataset.document,page:Number(paper.dataset.page),recipient:state.recipient,x:Math.max(0,Math.min(1-w,(clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1-h,(clientY-rect.top)/rect.height)),w,h,required:true};if(type==='dropdown')f.options=['Option 1','Option 2'];state.env.fields.push(f);state.field=f.id;state.tool=null;$$('[data-tool]').forEach(x=>x.classList.remove('active'));renderFields();$('#right-panel').innerHTML=rightPanel();markDirty();}
function startDrag(e,target,paper){e.preventDefault();const id=target.dataset.field;const grip=e.target.dataset.grip;state.field=id;snapshot();const f=state.env.fields.find(x=>x.id===id);const before={...f};const rect=paper.getBoundingClientRect();const start={x:e.clientX,y:e.clientY};renderFields();$('#right-panel').innerHTML=rightPanel();const moved=ev=>{const dx=(ev.clientX-start.x)/rect.width,dy=(ev.clientY-start.y)/rect.height;if(!grip){f.x=Math.max(0,Math.min(1-f.w,before.x+dx));f.y=Math.max(0,Math.min(1-f.h,before.y+dy));}else{if(grip.includes('e'))f.w=Math.max(.02,Math.min(1-f.x,before.w+dx));if(grip.includes('s'))f.h=Math.max(.015,Math.min(1-f.y,before.h+dy));if(grip.includes('w')){f.x=Math.max(0,Math.min(before.x+before.w-.02,before.x+dx));f.w=before.w+before.x-f.x;}if(grip.includes('n')){f.y=Math.max(0,Math.min(before.y+before.h-.015,before.y+dy));f.h=before.h+before.y-f.y;}}const el=$(`[data-field="${id}"]`);if(el)Object.assign(el.style,{left:f.x*100+'%',top:f.y*100+'%',width:f.w*100+'%',height:f.h*100+'%'});};const end=()=>{document.removeEventListener('pointermove',moved);document.removeEventListener('pointerup',end);document.removeEventListener('pointercancel',end);if(JSON.stringify(before)!==JSON.stringify(f))markDirty();else state.history.pop();$('#right-panel').innerHTML=rightPanel();};document.addEventListener('pointermove',moved);document.addEventListener('pointerup',end);document.addEventListener('pointercancel',end);}
async function pollChanges(){const d=state.env;if(!d)return;const data=await api(`envelopes/${d.id}/presence`,{method:'POST',body:{}});if(state.env!==d)return;const p=$('#presence');if(p)p.innerHTML=data.people.map((p,i)=>avatar(p.name,i)).join('');if(data.revision>d.revision&&!state.saving){if(state.dirty||state.signing||$('#dialog').open){if(!state.conflict)toast('A newer version is available. Your current work has been kept.');state.conflict=true;$('#save-state')&&($('#save-state').innerHTML='New changes available · <button class="text-link" data-action="conflict">Resolve</button>');}else{const fresh=await api('envelopes/'+d.id);if(state.env!==d)return;state.env=fresh;renderEditor();}}if(state.editorTab==='comments'&&!$('#comment-text')?.value)await loadComments();}
async function loadComments(){const d=state.env;if(!d||d.permission==='recipient'){if($('#comments-list'))$('#comments-list').innerHTML='<p class="form-help">Comments are for workspace collaborators.</p>';return;}const comments=await api(`envelopes/${d.id}/comments`);if(!$('#comments-list'))return;$('#comments-list').innerHTML=comments.map(c=>`<div class="comment ${c.resolved?'resolved':''}"><div class="between"><b>${esc(c.name.split('@')[0])}</b><small>${relative(c.created)}</small></div><p>${esc(c.body)}</p>${['owner','editor'].includes(d.permission)?`<button class="text-link" data-action="resolve-comment:${c.id}:${c.resolved?0:1}">${c.resolved?'Reopen':'Resolve'}</button>`:''}</div>`).join('')||'<p class="form-help">No comments yet. Start the conversation.</p>';}
function undo(redo=false){if(!canEdit())return;const from=redo?state.future:state.history,to=redo?state.history:state.future;if(!from.length)return;to.push(structuredClone(state.env.fields));state.env.fields=from.pop();state.field=null;renderFields();$('#right-panel').innerHTML=rightPanel();markDirty();}
async function review(){await save();if(state.dirty)throw new Error('Resolve unsaved changes before activating.');const d=state.env;validateDocument(d);modal('Review your agreement',`<div class="review-grid"><div class="review-box"><b>${d.documents.length} documents</b><small>${d.documents.reduce((n,x)=>n+x.pages.length,0)} pages ready</small></div><div class="review-box"><b>${d.recipients.length} recipients</b><small>${d.sequential?'Sequential':'Parallel'} signing order</small></div></div><div class="divider"></div><div class="form-field"><label for="review-title">Agreement name</label><input id="review-title" value="${esc(d.title)}" maxlength="200"></div><div class="form-field"><label for="review-message">Message to recipients</label><textarea id="review-message" maxlength="10000">${esc(d.message)}</textarea></div><div class="form-field"><label for="review-expires">Expiration date (optional)</label><input type="date" id="review-expires" min="${now().slice(0,10)}" value="${d.expires?.slice(0,10)||''}"></div><div class="notice">${isLocalDemo?'Activating locks this local document and lets you try signing in this browser. No document or signing request is sent.':'Activating locks document content and opens signing. You’ll receive links to share with your recipients. Email delivery is not configured.'}</div><p class="form-help">${isLocalDemo?'For a self-signing demo, use '+esc(state.user.email)+' as the recipient.':'Recipients must sign in with their listed email and have access to this private app.'}</p>`,btn('Back','close')+btn(isLocalDemo?'Activate for signing':'Activate & get links','activate','primary','send'));}
async function activate(){if(state.conflict)throw new Error('Resolve the newer agreement version before activation.');const d=state.env;d.title=$('#review-title').value.trim();d.message=$('#review-message').value;d.expires=$('#review-expires').value?$('#review-expires').value+'T23:59:59.999Z':'';markDirty();await save();if(state.dirty)return;const updated=await api(`envelopes/${d.id}/action`,{method:'POST',body:{revision:d.revision,action:'activate',payload:{}}});state.env=updated;updateList(updated);renderEditor();signingLinks();toast(isLocalDemo?'Agreement activated. Ready to sign in this browser.':'Agreement activated. Signing links are ready.');}
function signingLinks(){const d=state.env;if(isLocalDemo){modal('Local signing demo',`<div class="notice">This agreement is stored in this browser. Signing links do not transfer documents or invite other people.</div><p class="long-text">Use ${esc(state.user.email)} as the recipient to try signing. Use the backend edition for authenticated recipients and shared documents.</p>${hasAction(d)?btn('Sign your part','sign-own:'+d.id,'primary full-width','pen'):''}`,btn('Done','close'));return;}modal('Your agreement is ready to sign',`<div class="notice success">${icon('circlecheck')} Signing is open. Share a link with each recipient.</div><p class="form-help">Recipients need access to this app and must sign in with the email below. These links do not send email.</p>${d.recipients.filter(x=>x.role!=='cc').map((r,i)=>`<div class="recipient-card">${avatar(r.name,i)}<div class="grow"><b>${esc(r.name)}</b><small>${esc(r.email)}</small><small>Order ${r.order} · ${r.status}</small></div>${btn('Get link','link:'+r.id,'small')}</div>`).join('')}<div class="mt">${hasAction(d)?btn('Sign your part','sign-own:'+d.id,'primary full-width','pen'):''}</div>`,btn('Done','close','primary'));}
async function signingLink(recipient){if(isLocalDemo){localInfo();return;}const d=state.env;const result=await api(`envelopes/${d.id}/links`,{method:'POST',body:{recipient}});state.env=result.envelope;updateList(state.env);const r=d.recipients.find(x=>x.id===recipient);modal('Share signing link',`<div class="recipient-card">${avatar(r.name)}<div><b>${esc(r.name)}</b><small>${esc(r.email)}</small></div></div><p class="form-help">Share this link directly. The recipient must sign in with the email above and have access to the app.</p><div class="form-field"><label for="signing-link">Signing link</label><input id="signing-link" class="link-field" readonly value="${esc(result.url)}"></div><div class="notice">A signing link opens the agreement for the authenticated recipient. To cancel signing access, void the agreement.</div>`,btn('Close','close')+btn('Copy link','copy-link','primary','copy'));}
async function signOwn(id){const d=state.env?.id===id?state.env:await api('envelopes/'+id);const r=nextRecipients(d).find(x=>x.email.toLowerCase()===state.user.email);if(!r)throw new Error('No signing action is currently available for your account.');close();await navigate(`sign/${d.id}/${r.id}`);}
async function signField(id){const d=state.env;const f=d.fields.find(x=>x.id===id);const r=d.recipients.find(x=>x.id===state.signRecipient);if(!state.signing||!r||f.recipient!==r.id||r.status==='completed'||d.status!=='sent')return;if(f.type==='signature'||f.type==='initials'){signatureDialog(f);return;}const value=state.signValues[id]??({name:r.name,email:r.email,date:now().slice(0,10),company:state.profile.company||''}[f.type]||'');const label=esc(f.label||f.type);modal(label,`<div class="form-field"><label for="sign-value">${label}${f.required?' *':''}</label>${f.type==='checkbox'?`<label class="inline"><input type="checkbox" id="sign-value" ${value?'checked':''}> ${label}</label>`:f.type==='dropdown'?`<select id="sign-value"><option value="">Choose an option</option>${f.options.map(o=>`<option ${value===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select>`:`<input id="sign-value" value="${esc(value)}" type="${f.type==='email'?'email':f.type==='date'?'date':f.type==='number'?'number':'text'}" ${f.type==='date'?'readonly':''} maxlength="500">`}</div>`,btn('Cancel','close')+btn('Apply','apply-value','primary','check'));$('[data-action="apply-value"]').onclick=()=>{const input=$('#sign-value');const v=f.type==='checkbox'?input.checked:input.value;if(!valueValid(f,v)){toast('Please enter a valid value.',true);return;}state.signValues[f.id]=v;close();refreshSignProgress();};}
function signatureDialog(f){const rec=state.env.recipients.find(r=>r.id===state.signRecipient);const proposed=f.type==='initials'?initials(rec.name):state.profile.signature||rec.name;let mode='type';let drawn=false;function content(){modal(f.type==='initials'?'Add your initials':'Adopt your signature',`<div class="tabs" style="margin-bottom:22px"><button class="tab ${mode==='type'?'active':''}" data-action="signature-mode:type">Type</button><button class="tab ${mode==='draw'?'active':''}" data-action="signature-mode:draw">Draw</button><button class="tab ${mode==='upload'?'active':''}" data-action="signature-mode:upload">Upload</button></div>${mode==='type'?`<label for="signature-text">Your ${f.type==='initials'?'initials':'full name'}</label><input id="signature-text" value="${esc(proposed)}" maxlength="150"><div class="typed-signature" id="signature-preview">${esc(proposed)}</div>`:mode==='draw'?`<canvas class="signature-canvas" id="signature-canvas" width="1000" height="340" aria-label="Draw your signature"></canvas><div class="between"><span class="form-help">Use your mouse, touch, or stylus.</span><button class="text-link" data-action="clear-signature">Clear</button></div>`:`<label class="dropzone">${icon('upload')}<b>Upload your signature</b><p>PNG image, up to 250 KB</p><input type="file" id="signature-upload" accept="image/png"></label><div id="signature-image-preview" class="center mt"></div>`}<p class="form-help mt">By applying this signature, you confirm it represents your intent to sign this agreement.</p>`,btn('Cancel','close')+btn('Adopt & apply','apply-signature','primary','check'));$$('[data-action^="signature-mode:"]').forEach(b=>b.onclick=()=>{mode=b.dataset.action.split(':')[1];content();});if(mode==='type')$('#signature-text').oninput=e=>$('#signature-preview').textContent=e.target.value;if(mode==='draw'){drawn=false;const canvas=$('#signature-canvas'),ctx=canvas.getContext('2d');ctx.strokeStyle='#24263a';ctx.lineWidth=3;ctx.lineCap='round';ctx.lineJoin='round';let down=false;const point=e=>{const rect=canvas.getBoundingClientRect();return[(e.clientX-rect.left)*canvas.width/rect.width,(e.clientY-rect.top)*canvas.height/rect.height];};canvas.onpointerdown=e=>{down=true;drawn=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e));ctx.lineTo(...point(e));ctx.stroke();};canvas.onpointermove=e=>{if(down){ctx.lineTo(...point(e));ctx.stroke();}};canvas.onpointerup=canvas.onpointercancel=()=>down=false;$('[data-action="clear-signature"]').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);drawn=false;};}if(mode==='upload')$('#signature-upload').onchange=()=>task(async()=>{const file=$('#signature-upload').files[0];if(!file)return;if(file.size>250000||file.type!=='image/png')throw new Error('Use a PNG image under 250 KB.');const reader=new FileReader();reader.onload=()=>{$('#signature-image-preview').innerHTML=`<img alt="Your uploaded signature" style="max-width:100%;max-height:150px" src="${esc(reader.result)}">`;};reader.readAsDataURL(file);});$('[data-action="apply-signature"]').onclick=()=>task(async()=>{let value;if(mode==='type'){const text=$('#signature-text').value.trim();if(!text)throw new Error('Enter your name.');const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=230;const ctx=canvas.getContext('2d');ctx.fillStyle='#252638';let size=90;ctx.font=`italic ${size}px Georgia`;while(ctx.measureText(text).width>1160){size-=2;ctx.font=`italic ${size}px Georgia`;}ctx.fillText(text,20,150);value=canvas.toDataURL('image/png');}else if(mode==='draw'){if(!drawn)throw new Error('Draw your signature first.');value=$('#signature-canvas').toDataURL('image/png');}else{value=$('#signature-image-preview img')?.src;if(!value)throw new Error('Upload your signature first.');}state.signValues[f.id]=value;close();refreshSignProgress();});}content();}
function refreshSignProgress(){const top=$('#viewport')?.scrollTop||0;renderEditor();$('#viewport').scrollTop=top;}
function nextField(){const f=state.env.fields.find(f=>f.recipient===state.signRecipient&&f.required&&visible(f,state.signValues)&&!valueValid(f,state.signValues[f.id]));if(!f){toast('All required fields are complete. You can finish signing.');return;}const target=$(`[data-field="${f.id}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'});task(()=>signField(f.id));}
async function finish(){const d=state.env;if(state.conflict){const fresh=await api('envelopes/'+d.id);if(fresh.status!=='sent')throw new Error('This agreement is no longer open for signing.');state.env=fresh;state.conflict=false;}if(!state.consent){modal('Consent to electronic signing',`<p class="long-text">You can review and download this document before signing. By continuing, you agree to use electronic records and signatures for this agreement. ${isLocalDemo?'Your local demo identity, entered fields, and completion time will be saved in this browser.':'Your account identity, completed fields, and time of signing will be recorded.'}</p><p class="form-help">Select the consent checkbox in the signing panel, or accept below.</p>`,btn('Back','close')+btn('I agree','accept-consent','primary','check'));return;}for(const f of state.env.fields.filter(f=>f.recipient===state.signRecipient&&visible(f,state.signValues)))if(!valueValid(f,state.signValues[f.id])){await signField(f.id);return;}const updated=await api(`envelopes/${d.id}/action`,{method:'POST',body:{revision:state.env.revision,action:'sign',payload:{recipient:state.signRecipient,values:state.signValues,consent:true}}});state.env=updated;state.signValues=updated.values;updateList(updated);renderEditor();modal('Your signature is complete',`<div class="center"><div style="color:var(--green);margin:12px">${icon('circlecheck')}</div><h3>${updated.status==='completed'?'Everyone has signed.':'Your part is done.'}</h3><p class="muted small-text">${updated.status==='completed'?'Your completed agreement and signing record are ready to download.':'The agreement is now waiting for the remaining recipients.'}</p></div><div class="divider"></div>${btn('Download agreement','download:'+d.id,'full-width primary','download')}${btn('Download signing record','receipt:'+d.id,'full-width mt','shield')}`,btn('Back to agreements','go:agreements'));}
async function collaborators(){if(isLocalDemo){localInfo();return;}await save();const d=state.env;if(!['owner','editor'].includes(d.permission))throw new Error('Only workspace editors can manage collaboration.');const members=await api(`envelopes/${d.id}/members`);modal('Collaborate on this agreement',`<div class="notice">Editors can prepare drafts and leave comments. Viewers can read documents and activity. Each collaborator also needs access to this private app.</div><div class="recipient-card">${avatar(state.user.name)}<div class="grow"><b>${esc(d.ownerEmail)}</b><small>Agreement owner</small></div><span class="pill">Owner</span></div>${members.map(m=>`<div class="recipient-card">${avatar(m.email)}<div class="grow"><b>${esc(m.email)}</b><small>${m.role}</small></div>${d.permission==='owner'?ibtn('trash','remove-member:'+m.email,'Remove collaborator'):''}</div>`).join('')}${d.permission==='owner'?`<form id="member-form" class="mt"><label for="member-email">Add a collaborator</label><div class="row"><input type="email" id="member-email" placeholder="name@company.com" required><select id="member-role" style="width:120px"><option value="editor">Editor</option><option value="viewer">Viewer</option></select></div><button class="btn primary mt" type="submit">Grant access</button></form>`:''}<p class="form-help">This grants agreement access by account email. It does not send an invitation email.</p>`,btn('Done','close'));}
async function downloadAgreement(id){await save();const d=state.env?.id===id?state.env:await api('envelopes/'+id);if(state.signing&&Object.keys(state.signValues).some(k=>state.signValues[k]!==d.values[k]))toast('The download contains saved signatures. Finish signing to include your current changes.');toast('Preparing your PDF…');const bytes=await exportPDF(d,renderer);download(bytes,d.title+'.pdf','application/pdf');}
async function downloadRecord(id){const d=state.env?.id===id?state.env:await api('envelopes/'+id);download(await receiptPDF(d),d.title+' - Signing record.pdf','application/pdf');}
async function exportCsv(){const entries=state.selected.size?state.envelopes.filter(d=>state.selected.has(d.id)):filtered();const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Title','Status','Recipients','Documents','Created','Updated','Completed'],...entries.map(d=>[d.title,statusName(d),d.recipients.map(r=>r.email).join('; '),d.documents.length,d.created,d.updated,d.completed||''])];download('\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'velsign-agreements.csv','text/csv;charset=utf-8');toast('Agreement report exported.');}
function help(){modal('Welcome to Velsign',`${isLocalDemo?'<div class="notice">GitHub Pages edition: documents and notes stay in this browser. Identity verification and cross-user collaboration require the backend edition.</div><div class="divider"></div>':''}<div class="check-list">${(isLocalDemo?[['upload','Prepare your document','Upload a PDF, PNG, or JPG. Use local@velsign.example as the recipient and drag fields onto each page.'],['message','Keep document notes','Add and resolve notes. Your documents, notes, and drafts are saved in this browser.'],['send','Open local signing','Review and activate the agreement to lock its contents. Choose Sign this document to try the signing flow.'],['signature','Sign and download','Review the document, give consent, and complete required fields. Download the completed PDF and local signing record.']]:[['upload','Prepare your document','Upload a PDF, PNG, or JPG. Add recipients and drag assigned fields onto each page.'],['users','Work with your team','Grant editors or viewers access by email. Comments and presence update while you work.'],['send','Open signing','Review and activate the agreement. Share the signing links with recipients who have access to the app.'],['signature','Sign and download','Recipients sign in with their assigned email, review the document, consent, and complete required fields.']]).map(([i,t,p])=>`<div class="row">${icon(i)}<div><b class="small-text">${t}</b><p class="form-help">${p}</p></div></div>`).join('')}</div><div class="divider"></div><p class="form-help">Keyboard: Ctrl/⌘ K to search, Ctrl/⌘ S to save, Ctrl/⌘ Z to undo. Use arrow keys to move selected fields, Shift for larger steps, and Delete to remove.</p><p class="form-help">Velsign records an internal hash-chained activity history. Qualified signatures, external identity checks, trusted timestamps, and automated email delivery are not configured.</p>`,btn('Got it','close','primary'));}
function conflict(){modal('A newer version is available',`<p class="long-text">A collaborator changed this agreement while you were working. Your changes are still held on this screen.</p><div class="stack">${btn('Download my unsaved work','download-unsaved','','download')}${btn('Load latest version','reload-editor','primary','redo')}</div><p class="form-help">Loading the latest version discards unsaved edits on this screen. Download them first if you want a recovery copy.</p>`,btn('Keep working here','close'));}
function propertyChange(el){if(!canEdit())return;const f=state.env.fields.find(x=>x.id===state.field);if(!f)return;snapshot();const prop=el.dataset.prop;if(prop==='required')f.required=el.checked;else if(prop==='options')f.options=el.value.split('\n').map(x=>x.trim()).filter(Boolean);else if(['w','h'].includes(prop))f[prop]=Math.max(.02,Math.min(1-f[prop==='w'?'x':'y'],Number(el.value)/100));else if(prop==='conditionField'){if(el.value)f.condition={field:el.value,equals:''};else delete f.condition;$('#right-panel').innerHTML=rightPanel();}else if(prop==='conditionValue')f.condition.equals=el.value;else f[prop]=el.value;renderFields();markDirty();}
function localInfo(){modal('GitHub Pages edition',`<div class="notice">Your documents and edits are stored in this browser’s IndexedDB. They are not uploaded to a shared server.</div><p class="long-text">This edition supports document preparation, templates, local comments, self-signing, reports, and PDF downloads. Use the hosted backend edition for account-verified signatures and collaboration across people or devices.</p><p class="form-help">Clearing this site’s browser data removes local documents. Download important documents before clearing data.</p>`,btn('Close','close','primary'));}
const actions={
'local-info':localInfo,
'discard-signing':async to=>{state.signValues={...state.env.values};state.signing=false;close();await navigate(to);},
'close':close,'help':help,'new':()=>newAgreement(),'new-template':()=>newAgreement('template'),'create':createAgreement,'sample':sampleAgreement,'open':id=>{close();return navigate('agreement/'+id);},'go':to=>{close();newKind='agreement';return navigate(to);},'menu':envelopeMenu,'sign-own':signOwn,'refresh':async()=>{await bootstrap();renderView();toast('Workspace updated.');},'filter':async f=>{state.filter=f;state.search='';await navigate('agreements');},'table-filter':f=>{state.filter=f;renderView();},'clear-selection':()=>{state.selected.clear();renderView();},'export-csv':exportCsv,'save':async()=>{await save();if(!state.dirty)toast('All changes saved.');},'recipients':recipientsDialog,'review':review,'activate':activate,'signing-links':signingLinks,'link':signingLink,'copy-link':async()=>{const input=$('#signing-link');try{await navigator.clipboard.writeText(input.value);toast('Signing link copied.');}catch{input.focus();input.select();toast('Select and copy the signing link.');}},'collaborators':collaborators,'download':downloadAgreement,'receipt':downloadRecord,'undo':()=>undo(),'redo':()=>undo(true),'deselect':()=>{state.field=null;renderFields();$('#right-panel').innerHTML=rightPanel();},'toggle-tools':()=>$('.editor').classList.toggle('show-tools'),'toggle-properties':()=>$('.editor').classList.toggle('show-properties'),'editor-tab':tab=>{state.editorTab=tab;$('#left-panel').innerHTML=leftPanel();$$('.editor-tabs [data-action]').forEach(b=>b.classList.toggle('active',b.dataset.action==='editor-tab:'+tab));if(tab==='comments')return loadComments();bindPages();},'scroll-doc':id=>$('.paper[data-document="'+id+'"]').scrollIntoView({behavior:'smooth',block:'start'}),'delete-field':()=>{if(!canEdit())return;snapshot();const id=state.field;state.env.fields=state.env.fields.filter(x=>x.id!==id).map(f=>{if(f.condition?.field===id)delete f.condition;return f;});state.field=null;renderFields();$('#right-panel').innerHTML=rightPanel();markDirty();},'duplicate-field':()=>{if(!canEdit())return;const f=state.env.fields.find(x=>x.id===state.field);if(!f)return;snapshot();const copy={...structuredClone(f),id:uid(),x:Math.min(1-f.w,f.x+.02),y:Math.min(1-f.h,f.y+.02)};state.env.fields.push(copy);state.field=copy.id;renderFields();$('#right-panel').innerHTML=rightPanel();markDirty();},'auto-fields':()=>{if(!canEdit()||!state.env.documents.length)return;const d=state.env;const recipients=d.recipients.filter(r=>r.role==='signer');if(!recipients.length){return recipientsDialog();}snapshot();const doc=d.documents.at(-1);let added=0;for(const [i,r] of recipients.entries()){if(d.fields.some(f=>f.type==='signature'&&f.recipient===r.id))continue;const y=Math.max(.08,.765-i*.085);d.fields.push({id:uid(),type:'signature',recipient:r.id,document:doc.id,page:doc.pages.length-1,x:.12,y,w:.3,h:.05,required:true},{id:uid(),type:'date',recipient:r.id,document:doc.id,page:doc.pages.length-1,x:.6,y,w:.22,h:.04,required:true});added+=2;}renderFields();$('#right-panel').innerHTML=rightPanel();markDirty();toast(`${added} fields added. Review their positions before activating.`);},'add-document':async()=>{await save();uploads=[];uploadEpoch++;pendingUploads=0;modal('Add documents',`<label class="dropzone">${icon('upload')}<b>Choose documents</b><p>PDF, PNG, or JPG · Up to 10 MB each</p><input type="file" multiple id="upload-input" accept="application/pdf,image/png,image/jpeg"></label><div id="uploads"></div>`,btn('Cancel','close')+btn('Add to agreement','append-documents','primary'));},'append-documents':async()=>{if(pendingUploads)throw new Error('Wait until all documents finish uploading.');if(!uploads.length)throw new Error('Choose at least one document.');state.env.documents.push(...uploads);markDirty();await save();close();renderEditor();},'next-field':nextField,'finish':finish,'accept-consent':()=>{state.consent=true;close();$('#consent')&&($('#consent').checked=true);return finish();},'disclosure':()=>modal('Electronic records & signatures',`<div class="long-text">You may review and download the document before signing. By agreeing to electronic records and signatures, you consent to complete this agreement electronically.

${isLocalDemo?'This demo records a local profile, the information entered in assigned fields, your consent, and the completion time. It does not verify your identity.':'Velsign records your authenticated account email, the information entered in assigned fields, your consent, and the time of completion.'} Keep a downloaded copy of your agreement for your records.

If you do not wish to sign electronically, decline and contact the sender to request an alternative. This workspace does not provide qualified electronic signatures or external identity verification.</div>`,btn('Close','close','primary')),'decline':()=>reasonDialog('Decline agreement','decline',state.env.id),'void':id=>reasonDialog('Void agreement','void',id),'reason-submit':async()=>{const reason=$('#reason').value.trim();const d=state.env?.id===reasonState.id?state.env:await api('envelopes/'+reasonState.id);const updated=await api(`envelopes/${d.id}/action`,{method:'POST',body:{revision:d.revision,action:reasonState.action,payload:{reason,recipient:state.signRecipient}}});updateList(updated);if(state.env?.id===d.id){state.env=updated;renderEditor();}else renderView();close();toast('Agreement '+updated.status+'.');},'duplicate':async id=>{const d=await api(`envelopes/${id}/duplicate`,{method:'POST',body:{}});updateList(d);close();await navigate('agreement/'+d.id);toast('A new draft copy is ready.');},'use':async id=>{const d=await api(`envelopes/${id}/duplicate`,{method:'POST',body:{}});updateList(d);await navigate('agreement/'+d.id);return recipientsDialog();},'template':async id=>{const d=await api(`envelopes/${id}/duplicate`,{method:'POST',body:{kind:'template'}});updateList(d);close();toast('Template saved.');await navigate('templates');},'remove-member':async email=>{await api(`envelopes/${state.env.id}/members`,{method:'DELETE',body:{email}});await collaborators();toast('Collaborator access removed.');},'resolve-comment':async data=>{const [id,resolved]=data.split(':');await api(`envelopes/${state.env.id}/comments`,{method:'PATCH',body:{id,resolved:resolved==='1'}});await loadComments();},'document-text':async()=>{toast('Extracting document text…');const text=(await Promise.all(state.env.documents.map(doc=>renderer.text(doc,state.env.id)))).join('\n');modal('Document text',`<div class="long-text">${esc(text||'No extractable text. This document may contain scanned images.')}</div>`,btn('Close','close'));},'conflict':conflict,'download-unsaved':()=>download(JSON.stringify({agreement:state.env,signingValues:state.signValues},null,2),'velsign-unsaved-work.json','application/json'),'reload-editor':async()=>{const id=state.env.id;state.dirty=false;close();await openEditor(id,state.signing?{recipient:state.signRecipient}:null);},'leave-editor':()=>navigate('agreements'),'notifications':()=>{const pending=state.envelopes.filter(hasAction);modal('Your activity',pending.length?`<div class="stack">${pending.map(d=>`<div class="recipient-card"><span class="stat-icon">${icon('pen')}</span><div class="grow"><b>${esc(d.title)}</b><small>Ready for your signature</small></div>${btn('Open','sign-own:'+d.id,'small')}</div>`).join('')}</div>`:'<div class="empty">'+icon('circlecheck')+'<h3>You’re all caught up</h3><p>No agreements currently need your signature.</p></div>',btn('Close','close'));},'contact-new':()=>modal('Add contact',`<form id="contact-form"><div class="form-field"><label for="contact-name">Full name</label><input id="contact-name" required maxlength="150"></div><div class="form-field"><label for="contact-email">Email address</label><input type="email" id="contact-email" required></div><div class="form-field"><label for="contact-company">Company (optional)</label><input id="contact-company" maxlength="150"></div><button class="btn primary full-width" type="submit">Save contact</button></form>`),'contact-delete':id=>modal('Remove contact?',`<p class="long-text">This removes the contact from your address book. Existing agreements keep their recipients.</p>`,btn('Cancel','close')+btn('Remove','confirm-contact-delete:'+id,'danger')),'confirm-contact-delete':async id=>{await api('contacts',{method:'DELETE',body:{id}});close();await contactsView();},'settings-tab':tab=>{if(isLocalDemo&&tab==='workspace'){localInfo();return;}$$('.settings-nav button').forEach(b=>b.classList.toggle('active',b.dataset.action==='settings-tab:'+tab));$('#settings-content').innerHTML=tab==='profile'?profileSettings():tab==='appearance'?`<div class="panel settings-card"><h2>Appearance</h2><p>Choose the appearance of your workspace on this device.</p><div class="divider"></div><div class="between"><div><b class="small-text">Dark theme</b><p>Use a darker interface for your workspace.</p></div>${btn(document.body.classList.contains('dark')?'Switch to light':'Switch to dark','theme','','moon')}</div></div>`:`<div class="panel settings-card"><h2>Workspace & access</h2><p>Agreements are stored securely behind your account and the app’s access controls.</p><div class="settings-status"><span>Document storage</span><span class="status completed">Configured</span></div><div class="settings-status"><span>Agreement database</span><span class="status completed">Configured</span></div><div class="settings-status"><span>Account identity</span><span>ChatGPT sign-in</span></div><div class="settings-status"><span>Signing link delivery</span><span>Manual sharing</span></div><div class="settings-status"><span>Team collaboration</span><span>By agreement</span></div><p class="form-help mt">Use Share inside an agreement to grant editing or viewing access. Site access is managed separately from agreement access.</p><div class="divider"></div><a class="btn" href="/signout-with-chatgpt?return_to=/" target="_top">Sign out</a></div>`;},'theme':()=>{document.body.classList.toggle('dark');localStorage.setItem('velsign-theme',document.body.classList.contains('dark')?'dark':'light');actions['settings-tab']('appearance');},'seed':async()=>{await api('seed',{method:'POST',body:{}});await bootstrap();close();renderView();toast('Sample agreements added.');},'retry':async()=>{await bootstrap();await route();}
};
let reasonState;
function reasonDialog(title,action,id){reasonState={action,id};modal(title,`<div class="notice warning">${action==='void'?'Voiding closes this agreement and prevents further signatures.':'Declining closes this agreement for all recipients.'}</div><div class="form-field mt"><label for="reason">Reason</label><textarea id="reason" maxlength="1000" placeholder="Explain the reason…" required></textarea></div>`,btn('Cancel','close')+btn(action==='void'?'Void agreement':'Decline','reason-submit','danger'));}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.onclick)return;const [action,...params]=button.dataset.action.split(':');if(!actions[action])return;e.preventDefault();task(async()=>{if(button.disabled)return;button.disabled=true;try{await actions[action](params.join(':'));}finally{button.disabled=false;}});});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='mobile-nav')task(()=>navigate(el.value));if(el.id==='upload-input')task(()=>uploadFiles(el.files));if(el.id==='sort'){state.sort=el.value;renderView();}if(el.dataset.select){el.checked?state.selected.add(el.dataset.select):state.selected.delete(el.dataset.select);renderView();}if(el.id==='select-all'){for(const d of filtered().slice(0,state.route==='home'?6:200))el.checked?state.selected.add(d.id):state.selected.delete(d.id);renderView();}if(el.id==='field-recipient')state.recipient=el.value;if(el.id==='zoom'){state.zoom=Number(el.value);renderEditor();}if(el.id==='consent')state.consent=el.checked;if(el.dataset.prop)propertyChange(el);});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;renderView();$('#table-search').focus();$('#table-search').setSelectionRange(pos,pos);},200);}if(e.target.id==='global-search'){const q=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.search=q;state.filter='all';task(()=>navigate('agreements'));},450);}});
document.addEventListener('submit',e=>{const form=e.target;if(!['profile-form','comment-form','member-form','contact-form'].includes(form.id))return;e.preventDefault();task(async()=>{const submit=form.querySelector('[type=submit]');submit.disabled=true;try{if(form.id==='profile-form'){state.profile=await api('profile',{method:'POST',body:Object.fromEntries(new FormData(form))});toast('Profile saved.');}if(form.id==='comment-form'){const input=$('#comment-text');await api(`envelopes/${state.env.id}/comments`,{method:'POST',body:{body:input.value}});input.value='';await loadComments();}if(form.id==='member-form'){await api(`envelopes/${state.env.id}/members`,{method:'POST',body:{email:$('#member-email').value,role:$('#member-role').value}});await collaborators();toast('Agreement access granted.');}if(form.id==='contact-form'){await api('contacts',{method:'POST',body:{name:$('#contact-name').value,email:$('#contact-email').value,company:$('#contact-company').value}});close();await contactsView();toast('Contact saved.');}}finally{submit.disabled=false;}});});
document.addEventListener('keydown',e=>{const typing=e.target.matches('input,textarea,select,[contenteditable=true]');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();task(save);}if(!typing&&!$('#dialog').open){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);}if(state.field&&canEdit()){if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();actions['delete-field']();}if(e.key.startsWith('Arrow')){e.preventDefault();snapshot();const f=state.env.fields.find(x=>x.id===state.field);const step=e.shiftKey?.01:.002;if(e.key==='ArrowLeft')f.x=Math.max(0,f.x-step);if(e.key==='ArrowRight')f.x=Math.min(1-f.w,f.x+step);if(e.key==='ArrowUp')f.y=Math.max(0,f.y-step);if(e.key==='ArrowDown')f.y=Math.min(1-f.h,f.y+step);renderFields();markDirty();}}if(e.target.matches('[data-field]')&&['Enter',' '].includes(e.key)){e.preventDefault();if(state.signing)task(()=>signField(e.target.dataset.field));else{state.field=e.target.dataset.field;renderFields();$('#right-panel').innerHTML=rightPanel();}}}});
window.addEventListener('beforeunload',e=>{if(state.dirty||state.signing&&Object.keys(state.signValues).some(k=>state.signValues[k]!==state.env.values[k])){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>task(async()=>{if(pendingSignature()){const target=location.hash.slice(1);history.replaceState({},'','#sign/'+state.env.id+'/'+state.signRecipient);confirmLeaving(target);return;}if(state.dirty){await save();if(state.dirty){history.replaceState({},'','#agreement/'+state.env.id);conflict();return;}}await route();}));
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'list_agreements',title:'List agreements',description:'Read the agreements available in the current workspace.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{await bootstrap();return state.envelopes.map(d=>({id:d.id,title:d.title,status:d.status,kind:d.kind}));}},{name:'open_agreement',title:'Open agreement',description:'Open an accessible agreement in the editor without signing or activating it.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(typeof input?.id!=='string'||!state.envelopes.some(d=>d.id===input.id))throw new Error('Choose an accessible agreement ID.');await navigate('agreement/'+input.id);return{id:state.env.id,title:state.env.title,status:state.env.status};}},{name:'start_agreement_creation',title:'Start agreement creation',description:'Open the upload form. Does not create, activate, or send an agreement.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{newAgreement();return{form:'new-agreement',requires:'document and title'};}}];for(const tool of tools)try{Promise.resolve(ctx.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
async function start(){try{await bootstrap();await route();registerTools();if(!state.envelopes.length&&!state.env)modal('Make yourself at home',`<p class="long-text">Your workspace is ready. Upload your first agreement, or explore the signing flow with a few sample documents.</p><div class="review-grid"><div class="review-box"><b>Start your own</b><small>Upload a PDF and prepare it for signature.</small></div><div class="review-box"><b>Explore samples</b><small>Try the editor and sign a sample yourself.</small></div></div>`,btn('Add sample agreements','seed')+btn('Upload a document','new','primary','upload'));}catch(e){$('#app').innerHTML=`<div class="initial"><a class="brand" href="${esc(appURL())}">velsign<em>✳</em></a><h1>${e.status===401?'Your agreement workspace awaits':'Let’s reconnect your workspace'}</h1><p>${esc(e.message)}</p>${e.status===401?'<a class="btn primary" href="/signin-with-chatgpt?return_to=/" target="_top">Sign in to Velsign</a>':btn('Try again','retry','primary')}</div>`;}}
start();
